/**
 * Refund service.
 *
 * Handles refund requests for orders. A refund is allowed only when the order
 * exists, has not already been refunded, and the total is at least 10.
 */

import type { AppError, Result } from '../kernel/errors.js';
import { err, ok } from '../kernel/result.js';
import type { Order } from './order.service.js';
import { lookupOrder } from './order.service.js';

export function refundOrder(orderId: string): Result<Order, AppError> {
  const order = lookupOrder(orderId);

  if (!order) {
    return err({
      code: 'NOT_FOUND',
      message: `Order ${orderId} not found`,
    });
  }

  if (order.refunded) {
    return err({
      code: 'ALREADY_REFUNDED',
      message: `Order ${orderId} has already been refunded`,
    });
  }

  if (order.total < 10) {
    return err({
      code: 'INVALID_AMOUNT',
      message: `Order total must be at least 10 to refund, but order ${orderId} has total ${order.total}`,
    });
  }

  Object.assign(order, { refunded: true });
  return ok(order);
}

